  paisvasco_prov:     { viewBox:'0 0 900 600', transform:'translate(158.6,51) scale(1.6)',    provinces: PAIS_VASCO_PROV },
  navarra_r:          { viewBox:'0 0 900 600', transform:'translate(158.6,51) scale(1.6)',    provinces: NAVARRA_REG },
