// Variable global que apunta al conjunto activo
let ACTIVE_MAP_KEY = 'espana';
let ACTIVE_PROVINCES = SPAIN_PROVINCES; // alias mutable

// ─── Estado independiente por mapa autonómico ─────────
// Cada clave de MAP_CONFIGS tiene su propio objeto { regions:{}, candidates:[] }
const regionStates = {};

function _getOrCreateMapState(key) {
  if (!regionStates[key]) {
    const cands = MAP_CANDIDATES[key] || MAP_CANDIDATES.espana;
    const provinces = MAP_CONFIGS[key]?.provinces || SPAIN_PROVINCES;
    const regions = {};
    provinces.forEach(p => {
      regions[p.id] = {candidate:'tossup', split:null, value:p.seats, disabled:false, locked:false};
    });
    regionStates[key] = {
      candidates: cands.map(c => Object.assign({}, c, {seats:0})),
      regions
    };
  }
  return regionStates[key];
}

// ─── Función de cambio de mapa ────────────────────────
function switchMapRegion(key) {
  // Guardar estado actual antes de cambiar
  regionStates[ACTIVE_MAP_KEY] = {
    candidates: mapState.candidates,
    regions: mapState.regions
  };

  ACTIVE_MAP_KEY = key;
  const cfg = MAP_CONFIGS[key];
  ACTIVE_PROVINCES = cfg.provinces || SPAIN_PROVINCES;

  // Cargar estado propio de este mapa (o crearlo si es la primera vez)
  const saved = _getOrCreateMapState(key);
  mapState.candidates = saved.candidates;
  mapState.regions = saved.regions;
  mapState.selectedCandidate = null;

  // Ajustar viewBox del SVG
  const svg = document.getElementById('spain-map');
  if (svg) svg.setAttribute('viewBox', cfg.viewBox);

  // Ajustar baseTransform para zoom/pan
  mapViewState.baseTransform = cfg.transform;
  mapViewState.zoom = 1; mapViewState.panX = 0; mapViewState.panY = 0;

  renderSpainMap();
}

let mapState={
  mode:'fill',selectedCandidate:null,chartType:'battle',theme:'dark',showLabels:true,
  candidates: MAP_CANDIDATES.espana.map(c => Object.assign({}, c, {seats:0})),
  regions:{},
  savedMaps:JSON.parse(localStorage.getItem('bly-saved-maps')||'[]'),
};
ACTIVE_PROVINCES.forEach(p=>{mapState.regions[p.id]={candidate:'tossup',split:null,value:p.seats,disabled:false,locked:false};});
// Registrar el estado inicial de España para que switchMapRegion lo guarde/restaure correctamente
regionStates['espana'] = { candidates: mapState.candidates, regions: mapState.regions };
function getCandidateById(id){return mapState.candidates.find(c=>c.id===id);}

function getRegionFill(regionId){
  const r=mapState.regions[regionId];
  if(!r||r.disabled)return'#2a2a2a';
  if(r.split){let best='tossup',bestN=0;Object.entries(r.split).forEach(([cid,n])=>{if(n>bestN){bestN=n;best=cid;}});return getCandidateById(best)?.color||'#888';}
  return getCandidateById(r.candidate)?.color||'#888';
}

function countSeats(){
  const counts={};mapState.candidates.forEach(c=>{counts[c.id]=0;});
  ACTIVE_PROVINCES.forEach(p=>{
    const r=mapState.regions[p.id];if(!r||r.disabled)return;
    if(r.split){Object.entries(r.split).forEach(([cid,n])=>{if(counts[cid]!==undefined)counts[cid]+=n;});}
    else{if(counts[r.candidate]!==undefined)counts[r.candidate]+=r.value;}
  });
  mapState.candidates.forEach(c=>{c.seats=counts[c.id]||0;});
}

function renderSeatBar(){
  countSeats();
  const bar=document.getElementById('map-seat-bar');if(!bar)return;
  const nonTossup=mapState.candidates.filter(c=>c.id!=='tossup');
  bar.innerHTML=mapState.candidates.map((c,idx)=>{
    const sel=mapState.selectedCandidate===c.id;
    // Assign shortcut: tossup=0, first non-tossup=1, ..., 9th=9
    const shortcutIdx = c.id==='tossup' ? 0 : (nonTossup.indexOf(c)+1);
    const shortcutLabel = shortcutIdx>=0&&shortcutIdx<=9 ? `<span style="position:absolute;top:-5px;left:-4px;background:rgba(0,0,0,.7);color:#fff;font-size:8px;font-weight:700;border-radius:3px;padding:0 3px;font-family:var(--mono);">${shortcutIdx}</span>` : '';
    return`<div class="seat-chip" style="background:${c.id==='tossup'?'transparent':c.color+'22'};border:2px solid ${sel?'#fff':c.color};color:${c.id==='tossup'?'var(--text2)':c.color};position:relative;" onclick="selectCandidate('${c.id}')">
      ${shortcutLabel}
      ${c.id!=='tossup'?`<span style="width:8px;height:8px;border-radius:2px;background:${c.color};display:inline-block;flex-shrink:0;"></span>`:''}
      <span style="font-size:10px;">${c.id==='tossup'?'Tossup':c.name}</span>
      <strong style="font-size:11px;">${c.seats}</strong>
    </div>`;
  }).join('');
}

function selectCandidate(id){mapState.selectedCandidate=mapState.selectedCandidate===id?null:id;renderSeatBar();}

function buildScaledPath(p){
  // If province has a real path with scale/offset, apply transform
  if(p.pathScale){
    const s=p.pathScale,ox=p.pathOffset[0],oy=p.pathOffset[1];
    return {d:p.path, transform:`translate(${ox},${oy}) scale(${s})`};
  }
  return {d:p.path, transform:null};
}

function getProvinceLabelXY(p){
  if(p.pathScale){
    const s=p.pathScale,ox=p.pathOffset[0],oy=p.pathOffset[1];
    // Approximate centroid from pathOffset + half of typical province size
    return {x:ox+p.cx*s, y:oy+p.cy*s};
  }
  return {x:p.cx, y:p.cy};
}

function renderSpainMap(){
  const svg=document.getElementById('spain-map');if(!svg)return;svg.innerHTML='';
  const defs=document.createElementNS('http://www.w3.org/2000/svg','defs');svg.appendChild(defs);
  // Add main group with transform to scale/center map
  const mapG=document.createElementNS('http://www.w3.org/2000/svg','g');
  mapG.setAttribute('transform', MAP_CONFIGS[ACTIVE_MAP_KEY]?.transform || 'translate(158.6,51) scale(1.6)');
  svg.appendChild(mapG);
  ACTIVE_PROVINCES.forEach(p=>{
    const r=mapState.regions[p.id];const color=getRegionFill(p.id);
    const g=document.createElementNS('http://www.w3.org/2000/svg','g');
    const {d,transform}=buildScaledPath(p);
    const path=document.createElementNS('http://www.w3.org/2000/svg','path');
    path.setAttribute('d',d);
    if(transform)path.setAttribute('transform',transform);
    if(r&&r.split){
      // --- SMART SPLIT COLORING ---
      // Find the max seats assigned, then collect all parties tied at that max
      const entries=Object.entries(r.split).filter(([,n])=>n>0);
      if(entries.length>0){
        const maxSeats=Math.max(...entries.map(([,n])=>n));
        const winners=entries.filter(([,n])=>n===maxSeats);
        if(winners.length===1){
          // Clear winner → solid color
          const winColor=getCandidateById(winners[0][0])?.color||'#999';
          path.setAttribute('fill',winColor);
        }else{
          // Tie between 2+ parties → stripes of only the tied colors
          const patId='sp-'+p.id;
          const pat=document.createElementNS('http://www.w3.org/2000/svg','pattern');
          const stripeW=10/winners.length;
          pat.setAttribute('id',patId);pat.setAttribute('patternUnits','userSpaceOnUse');
          pat.setAttribute('width','10');pat.setAttribute('height','10');
          pat.setAttribute('patternTransform','rotate(-45 0 0)');
          winners.forEach(([cid],i)=>{
            const col=getCandidateById(cid)?.color||'#999';
            const rect=document.createElementNS('http://www.w3.org/2000/svg','rect');
            rect.setAttribute('x',String(i*stripeW));rect.setAttribute('width',String(stripeW));
            rect.setAttribute('height','10');rect.setAttribute('fill',col);
            pat.appendChild(rect);
          });
          defs.appendChild(pat);
          path.setAttribute('fill',`url(#${patId})`);
        }
      }else{path.setAttribute('fill',color);}
    }else{path.setAttribute('fill',color);}
    path.setAttribute('stroke',
      (mapState.theme==='dark'||mapState.theme==='dark2'||mapState.theme==='dark3')
        ? '#1a1a2e'
        : (mapState.theme==='light3' ? '#8faac8' : '#ffffff')
    );
    path.setAttribute('stroke-width',p.pathScale?'0.12':'1.2');
    path.style.cursor='pointer';path.addEventListener('mouseenter',()=>path.style.filter='brightness(1.3)');path.addEventListener('mouseleave',()=>path.style.filter='');
    path.addEventListener('click',()=>handleProvinceClick(p.id));
    g.appendChild(path);
    if(mapState.showLabels){
      const {x,y}=getProvinceLabelXY(p);
      const txt=document.createElementNS('http://www.w3.org/2000/svg','text');
      txt.setAttribute('x',x);txt.setAttribute('y',y-3);txt.setAttribute('text-anchor','middle');txt.setAttribute('dominant-baseline','middle');txt.setAttribute('font-size','3.5');txt.setAttribute('font-weight','600');txt.setAttribute('fill','#ffffff');txt.setAttribute('pointer-events','none');
      txt.textContent=p.name.length>8?p.name.substring(0,8)+'…':p.name;g.appendChild(txt);
      const s=document.createElementNS('http://www.w3.org/2000/svg','text');
      s.setAttribute('x',x);s.setAttribute('y',y+5);s.setAttribute('text-anchor','middle');s.setAttribute('dominant-baseline','middle');s.setAttribute('font-size','2.8');s.setAttribute('fill','rgba(255,255,255,0.8)');s.setAttribute('pointer-events','none');
      s.textContent=`(${r?r.value:p.seats})`;g.appendChild(s);
    }
    mapG.appendChild(g);
  });
  renderSeatBar();renderChart();renderSavedMapsSidebar();
}

function handleProvinceClick(provinceId){
  const r=mapState.regions[provinceId];if(!r)return;
  if(r.locked&&mapState.mode!=='lock')return;
  switch(mapState.mode){
    case 'fill':if(!mapState.selectedCandidate)return;r.candidate=mapState.selectedCandidate;r.split=null;break;
    case 'split':showSplitModal(provinceId);return;
    case 'edit':showEditRegionModal(provinceId);return;
    case 'disable':r.disabled=!r.disabled;break;
    case 'lock':r.locked=!r.locked;break;
  }
  renderSpainMap();
}

// ─── CHARTS ─────────────────────────────────────────────
function renderChart(){
  countSeats();
  const area=document.getElementById('map-chart-area');if(!area)return;
  const type=mapState.chartType||'battle';
  if(type==='none'){area.style.display='none';return;}
  area.style.display='';
  const parties=mapState.candidates.filter(c=>c.id!=='tossup'&&c.seats>0);
  const tossup=mapState.candidates.find(c=>c.id==='tossup');
  const total=350;
  if(type==='battle'){
    const assigned=parties.reduce((s,c)=>s+c.seats,0);
    const barHtml=parties.map(c=>`<div title="${c.name}: ${c.seats}" style="height:22px;width:${(c.seats/total*100).toFixed(2)}%;background:${c.color};display:inline-block;transition:width .4s;min-width:${c.seats>0?'2px':'0'};"></div>`).join('');
    const tossupW=Math.max(0,100-(assigned/total*100));
    area.innerHTML=`<div style="border-radius:5px;overflow:hidden;display:flex;width:100%;margin-bottom:6px;height:24px;">${barHtml}<div style="height:24px;flex:1;background:#3a3a4a;min-width:${assigned===0?'100%':'2px'};"></div></div>
      <div style="display:flex;justify-content:space-between;font-size:10px;color:var(--text3);">
        <span>Asignados: <strong style="color:var(--text)">${assigned}/350</strong></span>
        <span style="color:var(--gold);font-weight:700;">⚡ Mayoría: 176</span>
        <span>Sin asignar: ${tossup?.seats||0}</span>
      </div>`;
  }else if(type==='pie'||type==='doughnut'){
    const size=160,cx=80,cy=80,r=type==='doughnut'?55:68,innerR=type==='doughnut'?28:0;
    let start=-Math.PI/2;const tot=parties.reduce((s,c)=>s+c.seats,0)||1;
    let paths='';
    parties.forEach(c=>{
      const angle=(c.seats/tot)*2*Math.PI;const end=start+angle;
      if(angle<0.01){start=end;return;}
      const x1=cx+r*Math.cos(start),y1=cy+r*Math.sin(start);const x2=cx+r*Math.cos(end),y2=cy+r*Math.sin(end);const la=angle>Math.PI?1:0;
      let d;
      if(innerR>0){const ix1=cx+innerR*Math.cos(end),iy1=cy+innerR*Math.sin(end);const ix2=cx+innerR*Math.cos(start),iy2=cy+innerR*Math.sin(start);d=`M${x1},${y1}A${r},${r} 0 ${la},1 ${x2},${y2}L${ix1},${iy1}A${innerR},${innerR} 0 ${la},0 ${ix2},${iy2}Z`;}
      else{d=`M${cx},${cy}L${x1},${y1}A${r},${r} 0 ${la},1 ${x2},${y2}Z`;}
      const mid=start+angle/2;const lr=(innerR>0)?44:50;const lx=cx+lr*Math.cos(mid),ly=cy+lr*Math.sin(mid);
      paths+=`<path d="${d}" fill="${c.color}" stroke="#1a1a2e" stroke-width="0.5"/>`;
      if(c.seats>=10)paths+=`<text x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="middle" dominant-baseline="middle" font-size="7" font-weight="700" fill="white">${c.seats}</text>`;
      start=end;
    });
    const leg=parties.slice(0,9).map(c=>`<div style="display:flex;align-items:center;gap:4px;margin-bottom:2px;"><span style="width:8px;height:8px;border-radius:2px;background:${c.color};flex-shrink:0;display:inline-block;"></span><span style="font-size:9px;color:var(--text2);">${c.name}: <strong>${c.seats}</strong></span></div>`).join('');
    area.innerHTML=`<div style="display:flex;align-items:center;gap:12px;"><svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" style="flex-shrink:0;">${paths}</svg><div>${leg}</div></div>`;
  }else if(type==='arch'){
    // Parlamento de semiciclo profesional
    const totalSeats=350;
    const rows=5;
    // Distribuir escaños por fila (más en filas externas)
    const rowSeats=[55,63,71,78,83];
    const allSeats=[];
    parties.forEach(c=>{for(let i=0;i<c.seats;i++)allSeats.push(c.color);});
    while(allSeats.length<totalSeats)allSeats.push('#2e3650');
    // Sort so assigned seats cluster together
    let idx=0,dots='';
    const W=480,H=270,CX=W/2,CY=H-20;
    const rMin=80,rStep=32;
    rowSeats.forEach((n,ri)=>{
      const arcR=rMin+ri*rStep;
      const dotR=Math.min(5.5,Math.PI*arcR/n/2-0.8);
      for(let i=0;i<n;i++){
        const angle=Math.PI*(i/(n-1));
        const x=(CX-arcR*Math.cos(angle)).toFixed(1);
        const y=(CY-arcR*Math.sin(angle)).toFixed(1);
        const col=allSeats[idx++]||'#2e3650';
        dots+=`<circle cx="${x}" cy="${y}" r="${dotR.toFixed(1)}" fill="${col}" stroke="rgba(0,0,0,0.4)" stroke-width="0.5" opacity="0.95"/>`;
      }
    });
    // Línea base
    dots+=`<line x1="${CX-rMin-rStep*rows-10}" y1="${CY}" x2="${CX+rMin+rStep*rows+10}" y2="${CY}" stroke="rgba(255,255,255,0.08)" stroke-width="1"/>`;
    // Mayoría abs marker
    const majPct=176/totalSeats;
    dots+=`<line x1="${CX}" y1="${CY-rMin+10}" x2="${CX}" y2="${CY-rMin-rStep*rows-10}" stroke="rgba(245,183,49,0.5)" stroke-width="1.5" stroke-dasharray="4,3"/>`;
    dots+=`<text x="${CX+4}" y="${CY-rMin-rStep*rows-12}" font-size="9" fill="rgba(245,183,49,0.8)" font-family="Sora,sans-serif">176</text>`;
    const leg=parties.map(c=>`<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;"><span style="width:10px;height:10px;border-radius:50%;background:${c.color};flex-shrink:0;display:inline-block;box-shadow:0 0 4px ${c.color}66;"></span><span style="font-size:11px;color:var(--text2);white-space:nowrap;">${c.name}</span><strong style="font-size:11px;color:var(--text);margin-left:auto;">${c.seats}</strong></div>`).join('');
    const tossup=mapState.candidates.find(c=>c.id==='tossup');
    area.innerHTML=`<div style="display:flex;align-items:flex-end;gap:16px;padding:6px 0;">
      <svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" style="flex-shrink:0;overflow:visible;">${dots}</svg>
      <div style="min-width:110px;max-width:150px;padding-bottom:8px;">
        <div style="font-size:10px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;">Escaños</div>
        ${leg}
        ${tossup&&tossup.seats>0?`<div style="margin-top:6px;padding-top:6px;border-top:1px solid var(--border);font-size:10px;color:var(--text3);">Tossup: <strong style="color:var(--text);">${tossup.seats}</strong></div>`:''}
        <div style="margin-top:8px;padding-top:6px;border-top:1px solid var(--border);font-size:10px;color:var(--gold);">⚡ Mayoría: <strong>176</strong></div>
      </div>
    </div>`;
  }
}

// ─── MODALS ──────────────────────────────────────────────
function showMapModal(type){
  const overlay=document.getElementById('map-modal-overlay');const content=document.getElementById('map-modal-content');if(!overlay||!content)return;
  content.innerHTML=buildModalContent(type);overlay.classList.add('open');
  if(type==='candidates') setTimeout(initCandidateDragReorder, 0);
}
function closeMapModal(){const o=document.getElementById('map-modal-overlay');if(o)o.classList.remove('open');}

function buildModalContent(type){
  if(type==='clear')return`<div class="map-modal-title">🗑️ Limpiar Mapa</div><button class="map-modal-close" onclick="closeMapModal()">×</button><p style="font-size:13px;color:var(--text2);margin-bottom:16px;">Se eliminará todo el progreso. ¿Estás seguro?</p><label style="display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text2);margin-bottom:16px;cursor:pointer;"><input type="checkbox" id="clear-locks-check"> Limpiar también bloqueos</label><button class="map-btn map-btn-danger" onclick="doClearMap()">🗑️ Limpiar</button>`;
  if(type==='candidates')return buildCandidatesModal();
  if(type==='custom')return`<div class="map-modal-title">🗺️ Exportar</div><button class="map-modal-close" onclick="closeMapModal()">×</button><p style="font-size:13px;color:var(--text2);margin-bottom:14px;">Exporta como SVG.</p><button class="map-btn map-btn-primary" onclick="exportMapSVG()">⬇️ Exportar SVG</button>`;
  if(type==='options')return buildOptionsModal();
  if(type==='mode')return buildModeModal();
  if(type==='share')return buildShareModal();
  if(type==='shortcuts')return buildShortcutsModal();
  if(type==='theme')return buildThemeModal();
  if(type==='tools')return buildToolsModal();
  if(type==='regionstable')return buildRegionsTableModal();
  if(type==='account')return`<div class="map-modal-title">👤 Tu Cuenta</div><button class="map-modal-close" onclick="closeMapModal()">×</button><div style="text-align:center;padding:16px 0;"><div style="font-size:40px;margin-bottom:12px;">👤</div><p style="font-size:13px;color:var(--text2);">Usando Ballotly sin cuenta.</p><p style="font-size:11px;color:var(--text3);margin-top:6px;">Los mapas se guardan localmente.</p></div><button class="map-btn map-btn-primary" onclick="closeMapModal()">Continuar</button>`;
  return'';
}

function doClearMap(){
  const cl=document.getElementById('clear-locks-check')?.checked;
  ACTIVE_PROVINCES.forEach(p=>{const r=mapState.regions[p.id];if(!r||(r.locked&&!cl))return;r.candidate='tossup';r.split=null;r.disabled=false;if(cl)r.locked=false;});
  closeMapModal();renderSpainMap();
}

function buildCandidatesModal(){
  const chips=mapState.candidates.map(c=>`<div class="candidate-chip" draggable="true" data-cid="${c.id}" style="cursor:grab;"><div class="chip-drag-handle" style="color:var(--text3);font-size:12px;padding:0 4px 0 0;cursor:grab;user-select:none;">⠿</div><div class="chip-color" style="background:${c.color};"></div><span class="chip-name">${c.name}</span><strong style="font-size:10px;color:var(--text3);">${c.seats}</strong><button class="chip-menu" onclick="openEditCandidate('${c.id}')">≡</button></div>`).join('');
  return`<div class="map-modal-title">👥 Candidatos</div><button class="map-modal-close" onclick="closeMapModal()">×</button><p style="font-size:10px;color:var(--text3);margin-bottom:8px;">Mantén pulsado y arrastra para reordenar</p><div id="candidates-drag-list">${chips}</div><button class="map-btn map-btn-primary" style="margin-top:8px;" onclick="addNewCandidate()">+ Añadir</button>`;
}

function initCandidateDragReorder(){
  const list = document.getElementById('candidates-drag-list');
  if(!list) return;
  let dragging = null;

  list.querySelectorAll('.candidate-chip').forEach(chip => {
    chip.addEventListener('dragstart', e => {
      dragging = chip;
      chip.style.opacity = '0.4';
      chip.style.cursor = 'grabbing';
      e.dataTransfer.effectAllowed = 'move';
    });
    chip.addEventListener('dragend', () => {
      chip.style.opacity = '1';
      chip.style.cursor = 'grab';
      list.querySelectorAll('.candidate-chip').forEach(c => c.classList.remove('drag-over'));
      // Sync new order back to mapState.candidates
      const newOrder = [...list.querySelectorAll('.candidate-chip')].map(c => c.dataset.cid);
      mapState.candidates.sort((a,b) => newOrder.indexOf(a.id) - newOrder.indexOf(b.id));
      renderSeatBar();
      dragging = null;
    });
    chip.addEventListener('dragover', e => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      if(chip === dragging) return;
      list.querySelectorAll('.candidate-chip').forEach(c => c.classList.remove('drag-over'));
      chip.classList.add('drag-over');
      const rect = chip.getBoundingClientRect();
      const mid = rect.top + rect.height / 2;
      if(e.clientY < mid) {
        list.insertBefore(dragging, chip);
      } else {
        list.insertBefore(dragging, chip.nextSibling);
      }
    });
    chip.addEventListener('dragleave', () => chip.classList.remove('drag-over'));
    chip.addEventListener('drop', e => { e.preventDefault(); chip.classList.remove('drag-over'); });
  });
}
function openEditCandidate(id){const c=getCandidateById(id);if(!c)return;const content=document.getElementById('map-modal-content');if(!content)return;const isDefault=id==='tossup';content.innerHTML=`<div class="map-modal-title">✏️ Editar</div><button class="map-modal-close" onclick="showMapModal('candidates')">←</button><div class="ig"><label class="il">Nombre</label><input class="if" id="edn" value="${c.name}"></div><div class="ig"><label class="il">Color</label><input type="color" class="if" id="edc" value="${c.color}" style="height:40px;padding:4px;cursor:pointer;"></div><div style="display:flex;gap:8px;margin-top:12px;"><button class="map-btn map-btn-primary" style="flex:1;" onclick="saveEC('${id}')">Guardar</button>${!isDefault?`<button class="map-btn map-btn-danger" style="flex:1;" onclick="deleteCandidate('${id}')">Eliminar</button>`:''}</div>`;}
function saveEC(id){const c=getCandidateById(id);if(!c)return;c.name=document.getElementById('edn')?.value||c.name;c.color=document.getElementById('edc')?.value||c.color;showMapModal('candidates');renderSpainMap();}
function deleteCandidate(id){mapState.candidates=mapState.candidates.filter(c=>c.id!==id);ACTIVE_PROVINCES.forEach(p=>{if(mapState.regions[p.id]?.candidate===id)mapState.regions[p.id].candidate='tossup';});showMapModal('candidates');renderSpainMap();}
function addNewCandidate(){const nid='cand_'+Date.now();mapState.candidates.push({id:nid,name:'Nuevo Partido',color:'#888888',seats:0});openEditCandidate(nid);}

function buildOptionsModal(){
  return`<div class="map-modal-title">⚙️ Opciones</div><button class="map-modal-close" onclick="closeMapModal()">×</button>
    <div class="ig"><label class="il">Tipo de gráfico</label><select class="if" onchange="mapState.chartType=this.value;closeMapModal();renderChart();">
      <option value="battle" ${mapState.chartType==='battle'?'selected':''}>Battle (barra horizontal)</option>
      <option value="pie" ${mapState.chartType==='pie'?'selected':''}>Pie (tarta)</option>
      <option value="doughnut" ${mapState.chartType==='doughnut'?'selected':''}>Doughnut (rosco)</option>
      <option value="arch" ${mapState.chartType==='arch'?'selected':''}>Arch (parlamento)</option>
      <option value="none" ${mapState.chartType==='none'?'selected':''}>Ninguno</option>
    </select></div>
    <label style="display:flex;align-items:center;justify-content:space-between;font-size:13px;margin-bottom:10px;">Mostrar etiquetas<input type="checkbox" ${mapState.showLabels?'checked':''} onchange="mapState.showLabels=this.checked;renderSpainMap();"></label>`;
}

function buildModeModal(){
  const modes=[{id:'fill',label:'FILL',desc:'Asigna todos los escaños al partido seleccionado'},{id:'split',label:'SPLIT',desc:'Divide los escaños entre varios partidos'},{id:'edit',label:'EDIT',desc:'Edita el número de escaños'},{id:'disable',label:'DISABLE',desc:'Activa/desactiva circunscripción'},{id:'lock',label:'LOCK',desc:'Bloquea para evitar cambios'}];
  return`<div class="map-modal-title">🔄 Cambiar Modo</div><button class="map-modal-close" onclick="closeMapModal()">×</button>${modes.map(m=>`<button class="map-btn ${m.id===mapState.mode?'map-btn-mode active-mode':'map-btn-mode'}" onclick="setMapMode('${m.id}')" style="margin-bottom:3px;">${m.label}</button><p style="font-size:10px;color:var(--text3);text-align:center;margin:0 0 9px;">${m.desc}</p>`).join('')}<p style="font-size:10px;color:var(--text3);text-align:center;line-height:1.8;">Atajos: <kbd style="background:var(--bg4);border:1px solid var(--border);padding:1px 5px;border-radius:3px;">f</kbd> rellenar (hold) · <kbd style="background:var(--bg4);border:1px solid var(--border);padding:1px 5px;border-radius:3px;">Ctrl+F</kbd> toggle fill<br><kbd style="background:var(--bg4);border:1px solid var(--border);padding:1px 5px;border-radius:3px;">R</kbd> recentrar · <kbd style="background:var(--bg4);border:1px solid var(--border);padding:1px 5px;border-radius:3px;">0–9</kbd> candidatos · <kbd style="background:var(--bg4);border:1px solid var(--border);padding:1px 5px;border-radius:3px;">s·e·d·l</kbd> modos</p>`;
}
function setMapMode(mode){mapState.mode=mode;const lbl=document.getElementById('map-mode-label');if(lbl)lbl.textContent=mode.toUpperCase();closeMapModal();}

function buildShareModal(){
  return`<div class="map-modal-title">🔗 Compartir</div><button class="map-modal-close" onclick="closeMapModal()">×</button>
    <div style="margin-bottom:12px;"><div class="stitle">Descargar</div><div style="display:flex;gap:8px;"><button class="map-btn map-btn-secondary" style="flex:1;" onclick="downloadMapJSON()">⬇️ .bly</button><button class="map-btn map-btn-secondary" style="flex:1;" onclick="exportMapSVG()">🖼️ SVG</button></div></div>
    <div><div class="stitle">Redes sociales</div><div style="display:flex;gap:8px;"><button class="map-btn map-btn-secondary" style="flex:1;" onclick="shareToTwitter()">🐦 Twitter/X</button><button class="map-btn map-btn-secondary" style="flex:1;" onclick="shareToWhatsApp()">💬 WhatsApp</button></div></div>`;
}
function shareToTwitter(){countSeats();const pp=mapState.candidates.find(c=>c.id==='pp')?.seats||0;const psoe=mapState.candidates.find(c=>c.id==='psoe')?.seats||0;const msg='Mi prediccion: PP '+pp+' · PSOE '+psoe+' escaños #Ballotly #EleccionesEspana';window.open('https://twitter.com/intent/tweet?text='+encodeURIComponent(msg),'_blank');}
function shareToWhatsApp(){countSeats();const pp=mapState.candidates.find(c=>c.id==='pp')?.seats||0;const psoe=mapState.candidates.find(c=>c.id==='psoe')?.seats||0;const msg='Mi prediccion electoral en Ballotly: PP '+pp+' escanos · PSOE '+psoe+' escanos. Quien gana segun tu?';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
function downloadMapJSON(){const blob=new Blob([JSON.stringify({regions:mapState.regions,candidates:mapState.candidates,timestamp:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='mapa.bly';a.click();URL.revokeObjectURL(url);}
function exportMapSVG(){const svg=document.getElementById('spain-map');if(!svg)return;const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='mapa.svg';a.click();URL.revokeObjectURL(url);}

function buildThemeModal(){
  const themes=[
    {id:'dark',   emoji:'🌙', title:'Oscuro Clásico',      sub:'Azul noche — tema por defecto'},
    {id:'dark2',  emoji:'🌌', title:'Oscuro Profundo',      sub:'Azul medianoche intenso'},
    {id:'dark3',  emoji:'🔥', title:'Oscuro Carbón',        sub:'Tonos cálidos, marrón oscuro'},
    {id:'light',  emoji:'☀️', title:'Claro Estándar',       sub:'Blanco limpio, bordes blancos'},
    {id:'light3', emoji:'🗺️', title:'Claro Suave',          sub:'Fondo azulado, bordes de mapa visibles'},
    {id:'light2', emoji:'🌿', title:'Claro Contraste Alto', sub:'Gris azulado, máxima legibilidad'},
  ];
  return`<div class="map-modal-title">🎨 Cambiar Tema</div><button class="map-modal-close" onclick="closeMapModal()">×</button>
    <p style="font-size:11px;color:var(--text3);margin-bottom:14px;">Elige el estilo visual de la aplicación</p>
    ${themes.map(th=>`<div onclick="setMapTheme('${th.id}')" style="display:flex;align-items:center;gap:12px;padding:13px 16px;background:var(--surface);border:2px solid ${mapState.theme===th.id?'var(--accent)':'var(--border)'};border-radius:10px;cursor:pointer;margin-bottom:8px;transition:border-color .15s;">
      <span style="font-size:26px;">${th.emoji}</span>
      <div style="flex:1;"><div style="font-size:13px;font-weight:700;">${th.title}</div><div style="font-size:10px;color:var(--text3);">${th.sub}</div></div>
      ${mapState.theme===th.id?'<span style="color:var(--accent);font-size:18px;">✓</span>':''}
    </div>`).join('')}`;
}
function setMapTheme(theme){
  mapState.theme=theme;
  // Apply body class for CSS variable themes
  document.body.classList.remove('theme-light2','theme-light3','theme-dark2','theme-dark3');
  if(theme==='light2') document.body.classList.add('theme-light2');
  else if(theme==='light3') document.body.classList.add('theme-light3');
  else if(theme==='dark2') document.body.classList.add('theme-dark2');
  else if(theme==='dark3') document.body.classList.add('theme-dark3');
  closeMapModal();
  renderSpainMap();
}

