// ─── ZOOM / PAN STATE ────────────────────────────────────
const mapViewState = {
  zoom: 1,
  panX: 0,
  panY: 0,
  isDragging: false,
  lastX: 0,
  lastY: 0,
  baseTransform: 'translate(158.6,51) scale(1.6)'
};

function getMapG() {
  const svg = document.getElementById('spain-map');
  if (!svg) return null;
  return svg.querySelector('g');
}

function applyMapTransform() {
  const g = getMapG();
  if (!g) return;
  // Parse base translate/scale from active config
  const cfg = MAP_CONFIGS[ACTIVE_MAP_KEY] || MAP_CONFIGS.espana;
  const m = cfg.transform.match(/translate\(([\d.+-]+),([\d.+-]+)\)\s*scale\(([\d.]+)\)/);
  const bx = m ? parseFloat(m[1]) : 158.6;
  const by = m ? parseFloat(m[2]) : 51;
  const bs = m ? parseFloat(m[3]) : 1.6;
  g.setAttribute('transform',
    `translate(${bx + mapViewState.panX},${by + mapViewState.panY}) scale(${bs * mapViewState.zoom})`
  );
}

function resetMapView() {
  mapViewState.zoom = 1;
  mapViewState.panX = 0;
  mapViewState.panY = 0;
  const g = getMapG();
  if (g) g.setAttribute('transform', mapViewState.baseTransform);
}

function initMapZoomPan() {
  const container = document.getElementById('map-svg-container');
  const svg = document.getElementById('spain-map');
  if (!container || !svg) return;

  // Wheel zoom
  container.addEventListener('wheel', e => {
    e.preventDefault();
    const delta = e.deltaY < 0 ? 1.12 : 0.89;
    mapViewState.zoom = Math.min(8, Math.max(0.4, mapViewState.zoom * delta));
    applyMapTransform();
  }, { passive: false });

  // Drag pan
  container.addEventListener('mousedown', e => {
    // Only pan with middle button or when zoom > 1
    if (e.button === 1 || (e.button === 0 && mapViewState.zoom > 1)) {
      mapViewState.isDragging = true;
      mapViewState.lastX = e.clientX;
      mapViewState.lastY = e.clientY;
      container.classList.add('pan-active');
      e.preventDefault();
    }
  });
  window.addEventListener('mousemove', e => {
    if (!mapViewState.isDragging) return;
    const dx = (e.clientX - mapViewState.lastX) / mapViewState.zoom;
    const dy = (e.clientY - mapViewState.lastY) / mapViewState.zoom;
    mapViewState.panX += dx;
    mapViewState.panY += dy;
    mapViewState.lastX = e.clientX;
    mapViewState.lastY = e.clientY;
    applyMapTransform();
  });
  window.addEventListener('mouseup', () => {
    if (mapViewState.isDragging) {
      mapViewState.isDragging = false;
      container.classList.remove('pan-active');
    }
  });

  // Touch pan/zoom
  let lastTouchDist = null;
  container.addEventListener('touchstart', e => {
    if (e.touches.length === 2) {
      lastTouchDist = Math.hypot(
        e.touches[1].clientX - e.touches[0].clientX,
        e.touches[1].clientY - e.touches[0].clientY
      );
    } else if (e.touches.length === 1) {
      mapViewState.isDragging = true;
      mapViewState.lastX = e.touches[0].clientX;
      mapViewState.lastY = e.touches[0].clientY;
    }
  });
  container.addEventListener('touchmove', e => {
    e.preventDefault();
    if (e.touches.length === 2) {
      const dist = Math.hypot(
        e.touches[1].clientX - e.touches[0].clientX,
        e.touches[1].clientY - e.touches[0].clientY
      );
      if (lastTouchDist) {
        const ratio = dist / lastTouchDist;
        mapViewState.zoom = Math.min(8, Math.max(0.4, mapViewState.zoom * ratio));
        applyMapTransform();
      }
      lastTouchDist = dist;
    } else if (e.touches.length === 1 && mapViewState.isDragging) {
      const dx = (e.touches[0].clientX - mapViewState.lastX) / mapViewState.zoom;
      const dy = (e.touches[0].clientY - mapViewState.lastY) / mapViewState.zoom;
      mapViewState.panX += dx;
      mapViewState.panY += dy;
      mapViewState.lastX = e.touches[0].clientX;
      mapViewState.lastY = e.touches[0].clientY;
      applyMapTransform();
    }
  }, { passive: false });
  container.addEventListener('touchend', () => {
    mapViewState.isDragging = false;
    lastTouchDist = null;
  });
}

// ─── KEYBOARD ────────────────────────────────────────────
// Fill-key hold state (pressing and holding F while clicking = fill mode)
let _fillKeyHeld = false;
let _fillToggleActive = false;

function updateFillIndicator() {
  const el = document.getElementById('fill-mode-indicator');
  if (!el) return;
  const active = _fillToggleActive || _fillKeyHeld;
  if (active && mapState.selectedCandidate) {
    const cand = getCandidateById(mapState.selectedCandidate);
    el.style.background = cand ? cand.color + 'cc' : 'rgba(79,142,247,.85)';
    el.textContent = `✏️ Rellenando: ${cand?.name || '—'} · Ctrl+F para desactivar`;
    el.classList.add('active');
  } else if (active && !mapState.selectedCandidate) {
    el.textContent = '⚠️ Selecciona un candidato primero (clic en barra superior)';
    el.style.background = 'rgba(239,83,80,.85)';
    el.classList.add('active');
  } else {
    el.classList.remove('active');
  }
}

document.addEventListener('keydown', e => {
  const panel = document.getElementById('panel-mapaelectoral');
  if (!panel || !panel.classList.contains('active')) return;
  if (document.activeElement && ['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)) return;

  // R → recentrar mapa
  if (e.key === 'r' || e.key === 'R') {
    resetMapView();
    return;
  }

  // Ctrl+F → toggle fill mode on/off
  if ((e.ctrlKey || e.metaKey) && (e.key === 'f' || e.key === 'F')) {
    e.preventDefault();
    _fillToggleActive = !_fillToggleActive;
    if (_fillToggleActive) {
      mapState.mode = 'fill';
      const lbl = document.getElementById('map-mode-label');
      if (lbl) lbl.textContent = 'FILL';
    }
    updateFillIndicator();
    return;
  }

  // F held → temporary fill mode (existing behaviour + indicator)
  if (e.key === 'f' || e.key === 'F') {
    e.preventDefault();
    e.stopPropagation();
    if (!_fillKeyHeld) {
      _fillKeyHeld = true;
      const prev = mapState.mode;
      mapState._prevMode = prev;
      mapState.mode = 'fill';
      const lbl = document.getElementById('map-mode-label');
      if (lbl) lbl.textContent = 'FILL';
    }
    updateFillIndicator();
    return;
  }

  // Ctrl+dimmer color shortcut
  if (e.ctrlKey && e.key.toLowerCase() === 'i') {
    e.preventDefault();
    // handled by global TAB_KEYS above
    return;
  }

  // 0-9 → select candidate by index
  if (e.key >= '0' && e.key <= '9') {
    const idx = parseInt(e.key);
    const cands = mapState.candidates.filter(c => c.id !== 'tossup');
    if (idx === 0) {
      mapState.selectedCandidate = 'tossup';
    } else if (cands[idx - 1]) {
      mapState.selectedCandidate = cands[idx - 1].id;
    }
    renderSeatBar();
    updateFillIndicator();
    return;
  }

  // Existing mode shortcuts
  const modeMap = { s: 'split', e: 'edit', d: 'disable', l: 'lock' };
  if (modeMap[e.key]) {
    setMapMode(modeMap[e.key]);
    _fillToggleActive = false;
    updateFillIndicator();
  }
});

document.addEventListener('keyup', e => {
  if ((e.key === 'f' || e.key === 'F') && _fillKeyHeld) {
    e.preventDefault();
    _fillKeyHeld = false;
    if (!_fillToggleActive) {
      mapState.mode = mapState._prevMode || 'fill';
      const lbl = document.getElementById('map-mode-label');
      if (lbl) lbl.textContent = (mapState.mode).toUpperCase();
    }
    updateFillIndicator();
  }
});

// ─── INIT ─────────────────────────────────────────────────
function initMapPanel(){
  // Sync selector with current state
  const sel = document.getElementById('map-region-switcher');
  if (sel) sel.value = ACTIVE_MAP_KEY;
  // Set viewBox for current map
  const svg = document.getElementById('spain-map');
  if (svg) svg.setAttribute('viewBox', MAP_CONFIGS[ACTIVE_MAP_KEY]?.viewBox || '0 0 900 600');
  renderSpainMap();
  loadSavedMapsFromStorage();
  initMapZoomPan();
}